def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 10:
        last_me, last_opp = history[-1]
        if last_opp == 'D':
            return 'D'
        return 'C'
    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c
    my_last, opp_last = history[-1]
    recent = history[-10:]
    recent_opp_d = 0
    for a, b in recent:
        if b == 'D':
            recent_opp_d += 1
    recent_opp_c = len(recent) - recent_opp_d
    opp_rate = opp_c / n
    if recent_opp_d >= 8:
        return 'D'
    if recent_opp_c >= 9:
        return 'C'
    if opp_rate >= 0.8:
        return 'C'
    if opp_rate <= 0.3:
        return 'D'
    if my_last == 'C' and opp_last == 'D':
        return 'D'
    if my_last == 'D' and opp_last == 'C':
        return 'C'
    if n >= 20:
        last20 = history[-20:]
        d_after_d = 0
        for i in range(1, len(last20)):
            if last20[i-1][1] == 'D' and last20[i][1] == 'D':
                d_after_d += 1
        if d_after_d >= 5:
            return 'D'
    if opp_rate > 0.5:
        return 'C'
    return 'C' if rng.random() < 0.5 else 'D'
